64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    /**
72	     * Assigns the monotonically increasing sequence number carried by each structured
73	     * {@link OwnerCreatedEvent}. Static so the order spans every create handled by this endpoint,
74	     * regardless of the controller instance, giving the audit event stream a total order.
75	     */
76	    private static final AtomicLong AUDIT_EVENT_SEQUENCE = new AtomicLong();
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
87	
88	    private final HttpServletRequest request;
89	
90	    /** HTTP header carrying the idempotency key for the create-owner endpoint. */
91	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper,
97	                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
98	                                 HttpServletRequest request) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
104	        this.request = request;
105	    }
